variants.schema.json:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "RedefinitionCard",
  "description": "A card under cards/redefinition/<name>/ encoding one witnessed identity between two expressions in a declared domain.",
  "type": "object",
  "required": ["name", "category", "source_form", "target_form", "domain", "cost_score", "witness_kind", "examples", "tags"],
  "properties": {
    "name": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]*$",
      "description": "snake_case identifier unique within cards/redefinition/"
    },
    "category": {
      "type": "string",
      "const": "redefinition"
    },
    "source_form": {
      "type": "string",
      "description": "sympy-parseable LHS expression"
    },
    "target_form": {
      "type": "string",
      "description": "sympy-parseable RHS expression; the identity claimed is source_form == target_form on `domain` under `condition`"
    },
    "domain": {
      "type": "string",
      "enum": ["real", "complex", "fp32", "fp64", "bitvec64", "modular_n", "positive_real", "integer"]
    },
    "condition": {
      "oneOf": [
        {"type": "string", "description": "sympy-parseable predicate; identity holds only when this evaluates to True"},
        {"type": "null"}
      ]
    },
    "cost_score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 100,
      "description": "relative cost in the substrate's default cost monoid; lower wins"
    },
    "proof_ref": {
      "oneOf": [
        {"type": "string", "description": "math card name OR the literal 'axiomatic'"},
        {"type": "null"}
      ]
    },
    "witness_kind": {
      "type": "string",
      "enum": ["symbolic", "numerical", "exhaustive", "axiomatic"]
    },
    "examples": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["input", "source_eval", "target_eval"],
        "properties": {
          "input": {"type": "object", "description": "variable-name -> value"},
          "source_eval": {},
          "target_eval": {}
        }
      }
    },
    "tags": {
      "type": "array",
      "items": {"type": "string"}
    }
  },
  "additionalProperties": true
}
